# NS forest + MI genesimport pandas as pdimport numpy as npfrom sklearn.metrics import mutual_info_scorefrom collections import Counterfrom tqdm import tqdmfrom scipy.io import mmread minimal_set = pd.read_csv('/Users/ggraham/MERFISH/10_06_2025_minimal_set_MI.csv')NSmarkers =pd.read_csv("/Users/ggraham/MERFISH/NSForest Output/final_clusters2_markers.csv")NS_MI = minimal_set['symbol'].tolist() + NSmarkers['markerGene'].tolist()expression_matrix = mmread("/Users/ggraham/MERFISH/2025_10_06_genes_meeting_criteria.mtx")""" here, rows are genes (unlabeled) and columns are cells,all of the genes listed here are marker genes that fit Duncans criteriato save computation"""expression_matrix = pd.DataFrame(expression_matrix.toarray())"convert to a dataframe"genes = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_sparse_mat_rownames.csv")genes = genes['x']"""genes corresponds to the genes (rows) in expression matrix"""clusters = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_clusters.csv")"""clusters['clusters'] corresponds to the cluster label for each cell"""# Set up data structure like the originalexpression_matrix.index = genes  # Set gene names as index# Create labels dataframe - make sure cell names match expression matrix columnscell_names = expression_matrix.columns df_labels = pd.DataFrame({    'label': clusters['clusters'].values,    'cell_label': cell_names}, index=cell_names)#read in seurat marker genes## machine learning time babeyfrom sklearn.model_selection import cross_val_score, StratifiedKFoldfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import accuracy_scoreimport numpy as np    #pval # Prepare data - traNS_MIpose so cells are rows, genes are columNS_MINS_MI_X = expression_matrix.loc[NS_MI].TNS_MI_y = df_labels['label']# Initialize classifierNS_MI_clf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationNS_MI_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)NS_MI_cv_scores = cross_val_score(NS_MI_clf, NS_MI_X, NS_MI_y, cv=NS_MI_cv, scoring='accuracy')# Calculate metricsnp.mean(NS_MI_cv_scores) # up to 78%np.std(NS_MI_cv_scores)pd.DataFrame(NS_MI).to_csv('/Users/ggraham/Desktop/multiome_poa/MERFISH/10_07_2025_NS_MI_78acc.csv')Counter(NS_MI)